<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Browse our departments and courses. Find the right classes for your academic journey.</p>

<section class="mb-5">
    <h2>Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text">@course.Credits credits &middot; @course.InstructorName</p>
                        <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2>Departments</h2>
    <div class="list-group">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                <div>
                    <strong>@dept.Name</strong> <span class="text-muted">(@dept.Code)</span>
                    <br /><small class="text-muted">@dept.Description</small>
                </div>
                <span class="badge bg-primary rounded-pill">@courseCounts[dept.Id]</span>
            </a>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];
    private Dictionary<int, int> courseCounts = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
        var allCourses = Catalog.GetAllCourses();
        courseCounts = departments.ToDictionary(d => d.Id, d => allCourses.Count(c => c.DepartmentId == d.Id));
    }
}
